using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor injection — the MCP SDK resolves this from the DI container.
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool(Name = "get_weather"),
     Description("Get current weather for a city. Returns temperature and conditions.")]
    public async Task<string> GetWeatherAsync(
        [Description("City name, e.g. 'Seattle'")] string city,
        [Description("Unit system: 'metric' or 'imperial'")] string units = "metric")
    {
        // Example using Open-Meteo (free, no key required) via geocoding + forecast.
        var geo = await _httpClient.GetFromJsonAsync<GeoResponse>(
            $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(city)}&count=1");

        if (geo?.Results is not [var loc, ..])
            return $"Could not find location: {city}";

        var tempUnit = units == "imperial" ? "fahrenheit" : "celsius";
        var forecast = await _httpClient.GetFromJsonAsync<ForecastResponse>(
            $"https://api.open-meteo.com/v1/forecast?latitude={loc.Latitude}&longitude={loc.Longitude}" +
            $"&current_weather=true&temperature_unit={tempUnit}");

        if (forecast?.CurrentWeather is null)
            return "Weather data unavailable.";

        var w = forecast.CurrentWeather;
        var unitLabel = units == "imperial" ? "°F" : "°C";
        return $"{city}: {w.Temperature}{unitLabel}, wind {w.Windspeed} km/h, code {w.Weathercode}";
    }

    [McpServerTool(Name = "get_forecast"),
     Description("Get a 3-day temperature forecast for a city.")]
    public async Task<string> GetForecastAsync(
        [Description("City name")] string city)
    {
        var geo = await _httpClient.GetFromJsonAsync<GeoResponse>(
            $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(city)}&count=1");

        if (geo?.Results is not [var loc, ..])
            return $"Could not find location: {city}";

        var forecast = await _httpClient.GetFromJsonAsync<DailyForecastResponse>(
            $"https://api.open-meteo.com/v1/forecast?latitude={loc.Latitude}&longitude={loc.Longitude}" +
            $"&daily=temperature_2m_max,temperature_2m_min&forecast_days=3&timezone=auto");

        if (forecast?.Daily is null)
            return "Forecast data unavailable.";

        var lines = forecast.Daily.Time.Select((date, i) =>
            $"  {date}: {forecast.Daily.TemperatureMin[i]}–{forecast.Daily.TemperatureMax[i]}°C");

        return $"{city} 3-day forecast:\n{string.Join("\n", lines)}";
    }

    // --- DTOs for the Open-Meteo API ---

    private record GeoResponse(
        [property: JsonPropertyName("results")] GeoResult[]? Results);

    private record GeoResult(
        [property: JsonPropertyName("latitude")] double Latitude,
        [property: JsonPropertyName("longitude")] double Longitude);

    private record ForecastResponse(
        [property: JsonPropertyName("current_weather")] CurrentWeather? CurrentWeather);

    private record CurrentWeather(
        [property: JsonPropertyName("temperature")] double Temperature,
        [property: JsonPropertyName("windspeed")] double Windspeed,
        [property: JsonPropertyName("weathercode")] int Weathercode);

    private record DailyForecastResponse(
        [property: JsonPropertyName("daily")] DailyData? Daily);

    private record DailyData(
        [property: JsonPropertyName("time")] string[] Time,
        [property: JsonPropertyName("temperature_2m_max")] double[] TemperatureMax,
        [property: JsonPropertyName("temperature_2m_min")] double[] TemperatureMin);
}

